import re,os
def mod2path(m):
    return m.replace('.','/')+'.lean'
def imports(p):
    try: t=open(p).read()
    except: return []
    return re.findall(r'^import\s+(AlgebraicJacobian[\w.]*)',t,re.M)
seen=set()
stack=imports('AlgebraicJacobian.lean')
while stack:
    m=stack.pop()
    if m in seen: continue
    seen.add(m)
    stack+=imports(mod2path(m))
all_mods=set()
for root,_,fs in os.walk('AlgebraicJacobian'):
    for f in fs:
        if f.endswith('.lean'):
            all_mods.add(os.path.join(root,f)[:-5].replace('/','.'))
unreach=sorted(all_mods-seen)
print('total modules under AlgebraicJacobian/:',len(all_mods))
print('reachable from root:',len(all_mods&seen))
print('UNREACHABLE:',len(unreach))
EOF
